function demoMain(idx,label){
  var grams=[["expr: term (('+'|'-') term)*","LALR(1), 0 conflicts"],["json: object|array","recursive descent"],["csv: row*","DFA"]];
  var g=grams[idx%grams.length];
  return "["+label+"] grammar '"+g[0]+"' -> "+g[1];
}

